INSERT INTO domain_member_role (domain_member_id, domain_role_id, created_at)
SELECT dm.id, dr.id, CURRENT_TIMESTAMP(3)
FROM domain_member dm
JOIN domain_role dr ON dr.business_domain_id = dm.business_domain_id
JOIN role r ON r.code = dr.code
WHERE dm.staff_account_id = #{userId}
  AND dm.business_domain_id = #{businessDomainId}
  AND r.id = #{roleId}
  AND dm.deleted_at IS NULL
ON DUPLICATE KEY UPDATE created_at = VALUES(created_at)
